		Register.objects.create(lastname=lastname, firstname=firstname, nickname=nickname, gender=gender, address=address, nationality=nationality, birthdate=datetime.strptime(birthdate, "%Y-%m-%d"), spneeds=spneeds, accommodation=accommodation, allergy=allergy, glastname=glastname, gfirstname=gfirstname, email_add=emailadd, mobile=mobile, relationship=relationship, parent=parent, pnumber=pnumber, dgroupmember=dgroupmember, pdglead=pdglead, cluster=cluster, k_id=k_id, user_id=user_id)
